style.css:
@-moz-document domain("youtube.com") {
/* Ana arka plan görseli */
  html, body, ytd-app {
    background: url("https://images.alphacoders.com/638/638525.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Tüm içerik katmanlarını şeffaf yap */
  *, *::before, *::after {
    background-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Menüleri vs biraz karartarak görünür tut */
  ytd-popup-container, tp-yt-paper-dialog, .style-scope.ytd-popup-container {
    background-color: rgba(0, 0, 0, 0.7) !important;
  }

  /* Videoların üstündeki kutuları koruyalım */
  ytd-player, #movie_player {
    background-color: black !important;
  }

  /* Kaydırma çubuğunu gizle (isteğe bağlı) */
  ::-webkit-scrollbar {
    width: 8px;
    background: transparent !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.3) !important;
    border-radius: 4px;
  }
}
